{"content":"package grpc_inbound_adapter

import (
	"context"
	"os"
	"strings"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/metadata"
	"google.golang.org/grpc/status"

	"prabogo/internal/domain"
	inbound_port "prabogo/internal/port/inbound"
	"prabogo/utils/activity"
	"prabogo/utils/jwt"
)

const (
	authorizationHeader = "authorization"
	bearerPrefix        = "Bearer "
	bearerPrefixLen     = 7
)

type middlewareAdapter struct {
	domain domain.Domain
}

func NewMiddlewareAdapter(
	domain domain.Domain,
) inbound_port.MiddlewareGrpcPort {
	return &middlewareAdapter{
		domain: domain,
	}
}

func extractBearerToken(ctx context.Context) string {
	md, ok := metadata.FromIncomingContext(ctx)
	if !ok {
		return ""
	}

	values := md.Get(authorizationHeader)
	if len(values) == 0 {
		return ""
	}

	authHeader := values[0]
	if len(authHeader) > bearerPrefixLen && strings.EqualFold(authHeader[:bearerPrefixLen], bearerPrefix) {
		return authHeader[bearerPrefixLen:]
	}

	return ""
}

func (h *middlewareAdapter) InternalAuth(ctx context.Context, _ string) error {
	bearerToken := extractBearerToken(ctx)
	if bearerToken == "" {
		return status.Error(codes.Unauthenticated, "Unauthorized")
	}

	if bearerToken != os.Getenv("INTERNAL_KEY") {
		return status.Error(codes.Unauthenticated, "Unauthorized")
	}

	return nil
}

func (h *middlewareAdapter) ClientAuth(ctx context.Context, _ string) error {
	ctx = activity.NewContext("grpc_client_auth")
	bearerToken := extractBearerToken(ctx)
	if bearerToken == "" {
		return status.Error(codes.Unauthenticated, "Unauthorized")
	}

	authDriver := os.Getenv("AUTH_DRIVER")
	if authDriver == "jwt" {
		jwksURL := os.Getenv("AUTH_JWKS_URL")

		_, err := jwt.ValidateJWTWithURL(bearerToken, jwksURL)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "Unauthorized: %s", err.Error())
		}
	} else {
		exists, err := h.domain.Client().IsExists(ctx, bearerToken)
		if err != nil {
			return status.Errorf(codes.Internal, "%s", err.Error())
		}

		if !exists {
			return status.Error(codes.Unauthenticated, "Unauthorized")
		}
	}

	return nil
}","filePath":"/Users/dzulqaidar/go/src/prabogo/prabogo/internal/adapter/inbound/grpc/middleware.go"}

