{"content":"package grpc_inbound_adapter

import (
	"context"

	"github.com/palantir/stacktrace"
	"google.golang.org/grpc/codes"
	"google.golang.org/protobuf/types/known/timestamppb"
	"google.golang.org/grpc/status"

	"prabogo/internal/adapter/inbound/grpc/pb"
	"prabogo/internal/model"
	inbound_port "prabogo/internal/port/inbound"
)

type server struct {
	pb.UnimplementedPrabogoServiceServer
	port inbound_port.GrpcPort
}

func NewServer(port inbound_port.GrpcPort) pb.PrabogoServiceServer {
	return &server{
		port: port,
	}
}

func (s *server) Ping(ctx context.Context, _ *pb.PingRequest) (*pb.PingResponse, error) {
	if err := s.port.Middleware().ClientAuth(ctx, ""); err != nil {
		return nil, err
	}

	resource, err := s.port.Ping().GetResource(ctx)
	if err != nil {
		return nil, status.Errorf(codes.Internal, "http ping failed: %s", stacktrace.RootCause(err).Error())
	}

	core := make([]*pb.CoreInfo, 0, len(resource.Core))
	for _, c := range resource.Core {
		core = append(core, &pb.CoreInfo{Core: c.Core})
	}

	cpu := make([]*pb.CpuInfo, 0, len(resource.CPU))
	for _, c := range resource.CPU {
		cpu = append(cpu, &pb.CpuInfo{
			Usage: c.Usage,
			Busy:  c.Busy,
			Total: c.Total,
		})
	}

	memory := make([]*pb.MemoryInfo, 0, len(resource.Memory))
	for _, m := range resource.Memory {
		memory = append(memory, &pb.MemoryInfo{
			Usage:  m.Usage,
			Total:  m.Total,
			Free:   m.Free,
			Buffer: m.Buffer,
			Cached: m.Cached,
		})
	}

	return &pb.PingResponse{
		Message: resource.Message,
		Core:    core,
		Cpu:     cpu,
		Memory:  memory,
	}, nil
}

func (s *server) UpsertClient(ctx context.Context, req *pb.UpsertClientRequest) (*pb.UpsertClientResponse, error) {
	if err := s.port.Middleware().InternalAuth(ctx, ""); err != nil {
		return nil, err
	}

	inputs := make([]model.ClientInput, 0, len(req.GetInputs()))
	for _, in := range req.GetInputs() {
		inputs = append(inputs, pbClientInputToModel(in))
	}

	results, err := s.port.Client().Upsert(ctx, inputs)
	if err != nil {
		return &pb.UpsertClientResponse{
			Success: false,
			Error:   fmtRootCause(err),
		}, nil
	}

	return &pb.UpsertClientResponse{
		Success: true,
		Data:    modelClientsToPb(results),
	}, nil
}

func (s *server) FindClient(ctx context.Context, req *pb.FindClientRequest) (*pb.FindClientResponse, error) {
	if err := s.port.Middleware().InternalAuth(ctx, ""); err != nil {
		return nil, err
	}

	filter := pbClientFilterToModel(req.GetFilter())
	results, err := s.port.Client().Find(ctx, filter)
	if err != nil {
		return &pb.FindClientResponse{
			Success: false,
			Error:   fmtRootCause(err),
		}, nil
	}

	return &pb.FindClientResponse{
		Success: true,
		Data:    modelClientsToPb(results),
	}, nil
}

func (s *server) DeleteClient(ctx context.Context, req *pb.DeleteClientRequest) (*pb.DeleteClientResponse, error) {
	if err := s.port.Middleware().InternalAuth(ctx, ""); err != nil {
		return nil, err
	}

	filter := pbClientFilterToModel(req.GetFilter())
	err := s.port.Client().Delete(ctx, filter)
	if err != nil {
		return &pb.DeleteClientResponse{
			Success: false,
			Error:   fmtRootCause(err),
		}, nil
	}

	return &pb.DeleteClientResponse{
		Success: true,
	}, nil
}

func pbClientInputToModel(in *pb.ClientInput) model.ClientInput {
	if in == nil {
		return model.ClientInput{}
	}

	input := model.ClientInput{
		Name:      in.GetName(),
		BearerKey: in.GetBearerKey(),
	}

	if in.GetCreatedAt() != nil {
		input.CreatedAt = in.GetCreatedAt().AsTime()
	}
	if in.GetUpdatedAt() != nil {
		input.UpdatedAt = in.GetUpdatedAt().AsTime()
	}

	return input
}

func pbClientFilterToModel(filter *pb.ClientFilter) model.ClientFilter {
	if filter == nil {
		return model.ClientFilter{}
	}

	m := model.ClientFilter{
		IDs:        make([]int, 0, len(filter.GetIds())),
		Names:      filter.GetNames(),
		BearerKeys: filter.GetBearerKeys(),
	}
	for _, id := range filter.GetIds() {
		m.IDs = append(m.IDs, int(id))
	}

	return m
}

func modelClientToPb(c model.Client) *pb.Client {
	return &pb.Client{
		Id: int64(c.ID),
		Input: &pb.ClientInput{
			Name:      c.Name,
			BearerKey: c.BearerKey,
			CreatedAt: timestamppb.New(c.CreatedAt),
			UpdatedAt: timestamppb.New(c.UpdatedAt),
		},
	}
}

func modelClientsToPb(clients []model.Client) []*pb.Client {
	out := make([]*pb.Client, 0, len(clients))
	for _, c := range clients {
		out = append(out, modelClientToPb(c))
	}
	return out
}","filePath":"/Users/dzulqaidar/go/src/prabogo/prabogo/internal/adapter/inbound/grpc/server.go"}

