				So(err, ShouldBeNil)
				So(resp.GetSuccess(), ShouldBeFalse)
				So(resp.GetError(), ShouldNotBeEmpty)
			})
		})

		Convey("Ping", func() {
			Convey("Client exists in cache", func() {
				os.Unsetenv("AUTH_DRIVER")
				defer os.Unsetenv("AUTH_DRIVER")

				mockClientCachePort.EXPECT().Get(gomock.Any()).Return(model.Client{
					ID: 1,
					ClientInput: model.ClientInput{
						Name:      "Test Client",
						BearerKey: "valid-client-key",
					},
				}, nil).Times(1)

				resp, err := client.Ping(withClientAuth(context.Background()), &pb.PingRequest{})
				So(err, ShouldBeNil)
				So(resp.GetMessage(), ShouldEqual, "pong")
				So(resp.GetCore(), ShouldHaveLength, 1)
				So(resp.GetCpu(), ShouldHaveLength, 1)
				So(resp.GetMemory(), ShouldHaveLength, 1)
			})

			Convey("Unauthorized", func() {
				os.Unsetenv("AUTH_DRIVER")
				defer os.Unsetenv("AUTH_DRIVER")

				_, err := client.Ping(context.Background(), &pb.PingRequest{})
				So(err, ShouldNotBeNil)
				So(status.Code(err), ShouldEqual, codes.Unauthenticated)
			})
		})
	})
